import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it, vi } from "vitest";
import { CampaignProgress } from "@/components/campaign-progress";
import {
  readCampaignProgress,
  type CampaignProgressData,
} from "@/lib/campaign-progress";

const { findMany, queueFindMany, aggregate } = vi.hoisted(() => ({
  findMany: vi.fn(),
  queueFindMany: vi.fn().mockResolvedValue([]),
  aggregate: vi.fn().mockResolvedValue({
    _max: { sentAt: null, cancelledAt: null, attemptedAt: null },
  }),
}));
vi.mock("@/lib/db", () => ({
  db: { campaign: { findMany }, send: { findMany: queueFindMany, aggregate } },
}));

vi.mock("next/navigation", () => ({ useRouter: () => ({ refresh: vi.fn() }) }));
vi.mock("@/lib/campaign-progress-actions", () => ({
  getCampaignProgress: vi.fn(),
}));
vi.mock("@/lib/launch-actions", () => ({ cancelEmails: vi.fn() }));

const batch: CampaignProgressData = {
  id: "00000000-0000-4000-8000-000000000001",
  createdAt: "2026-10-09T10:00:00Z",
  observedAt: "2026-10-09T10:00:33Z",
  finishedAt: null,
  sent: 0,
  queued: 0,
  failed: 0,
  cancelled: 0,
  review: 0,
  pendingDispatch: false,
  delays: [],
  outstanding: 0,
  sending: 0,
  nextSendAt: null,
};
const render = (data: CampaignProgressData) =>
  renderToStaticMarkup(createElement(CampaignProgress, { data }));

describe("History batch progress edge states", () => {
  it("describes cancellation without celebrating successful delivery", () => {
    const html = render({
      ...batch,
      cancelled: 3,
      finishedAt: batch.observedAt,
    });
    expect(html).toContain("0 sent, 3 cancelled, 0 failed");
    expect(html).not.toContain("ALL SENT");
    expect(html).not.toContain("All messages confirmed");
  });
  it("renders zero totals without invalid proportions or missing tiles", () => {
    const html = render(batch);
    expect(html).not.toMatch(/NaN|Infinity/);
    expect(html).toContain("0 of 0 sent");
    for (const label of ["Sent", "Queued", "Failed"])
      expect(html).toContain(`>${label}</dt>`);
    expect(html.match(/width:0%/g)).toHaveLength(5);
    expect(
      renderToStaticMarkup(createElement(CampaignProgress, { data: null })),
    ).toBe("");
  });

  it("keeps review-only batches active without claiming confirmed completion", () => {
    const html = render({ ...batch, review: 2 });
    expect(html).toContain("NEEDS REVIEW");
    expect(html).toContain("Delivery needs review · 2");
    expect(html).toContain(
      "0 sent, 0 queued, 0 failed, 0 cancelled, 2 need review out of 2",
    );
    expect(html).toContain("Sending");
    expect(html).not.toContain("All messages confirmed by the service.");
    expect(html).not.toContain("completion-check");
    expect(html).not.toContain("Remaining");
    expect(html).not.toContain("batch-countdown-track");
  });

  it("does not mistake the in-flight safety reservation for a one-recipient timer", () => {
    const html = render({
      ...batch,
      queued: 1,
      outstanding: 1,
      sending: 1,
      nextSendAt: "2026-10-09T10:01:33Z",
    });
    expect(html).toContain("CONFIRMING");
    expect(html).toContain("Awaiting confirmation");
    expect(html).not.toContain("1:00");
    expect(html).not.toContain("NEXT SEND");
    expect(html).not.toContain("Remaining");
    const complete = render({
      ...batch,
      sent: 1,
      finishedAt: "2026-10-09T10:00:40Z",
    });
    expect(complete).toContain("completion-check");
    expect(complete).toContain("ALL SENT");
    expect(complete).not.toContain("batch-countdown-track");
  });

  it("does not invent a countdown when the service has not scheduled a send", () => {
    const html = render({
      ...batch,
      queued: 1,
      outstanding: 1,
      pendingDispatch: true,
    });
    expect(html).toMatch(/timer-value[^>]*>Sending</);
    expect(html).toContain("BE PATIENT");
    expect(html).not.toContain("Mailloop retries automatically");
    expect(html).not.toContain("Cancel this email");
    expect(html).not.toContain("NEXT SEND");
    expect(html).not.toContain("Remaining");
  });

  it("hides timing for one selected recipient even with a future schedule", () => {
    const html = render({
      ...batch,
      queued: 1,
      outstanding: 1,
      nextSendAt: "2026-10-09T10:01:33Z",
    });
    expect(html).toMatch(/timer-value[^>]*>Sending</);
    expect(html).not.toContain("1:00");
    expect(html).not.toContain("EST. LEFT");
    expect(html).not.toContain("batch-countdown-track");
    expect(html).not.toContain("Remaining");
    expect(html).not.toContain("Mailloop retries automatically");
  });

  it("shows queued recovery guidance alongside deliveries needing review", () => {
    const html = render({
      ...batch,
      queued: 1,
      outstanding: 1,
      review: 1,
      pendingDispatch: true,
      delays: [
        {
          sendId: "email-1",
          recipient: "[REDACTED_EMAIL]",
          state: "READY",
          startedAt: batch.createdAt,
        },
      ],
      observedAt: "2026-10-09T10:04:00Z",
    });
    expect(html).toContain("Delivery needs review");
    expect(html).toContain("Mailloop retries automatically");
    expect(html).toContain("Cancel this email");
  });

  it.each([
    ["2026-10-09T10:03:59Z", false],
    ["2026-10-09T10:04:00Z", true],
  ])(
    "shows recovery and cancellation only after four minutes: %s",
    (observedAt, visible) => {
      const html = render({
        ...batch,
        queued: 1,
        outstanding: 1,
        pendingDispatch: true,
        delays: [
          {
            sendId: "email-1",
            recipient: "[REDACTED_EMAIL]",
            state: "READY",
            startedAt: batch.createdAt,
          },
        ],
        observedAt,
      });
      expect(html.includes("Mailloop retries automatically")).toBe(visible);
      expect(html.includes("Cancel this email")).toBe(visible);
    },
  );

  it("keeps the batch timer for the final in-flight message of a larger batch", () => {
    const html = render({
      ...batch,
      sent: 1,
      queued: 1,
      outstanding: 1,
      sending: 1,
      nextSendAt: "2026-10-09T10:00:40Z",
    });
    expect(html).toContain("0:12");
    expect(html).toContain("EST. LEFT");
    expect(html).toContain("Remaining");
  });

  it("retains service-delay warnings and uses the whole-batch estimate", () => {
    const html = render({
      ...batch,
      queued: 2,
      outstanding: 2,
      pendingDispatch: true,
      nextSendAt: "2026-10-09T10:00:40Z",
    });
    expect(html).toContain("0:22");
    expect(html).toContain('class="batch-countdown-track"');
    expect(html).toContain('class="batch-countdown-arc"');
    expect(html).toContain('r="53"');
    expect(html).toContain("EST. LEFT");
    expect(html).not.toContain("Waiting for delivery service");
    expect(html).toContain("Service delays can extend this estimate.");
  });

  it("includes processing time when the persisted wait has expired", () => {
    const html = render({
      ...batch,
      sent: 1,
      queued: 1,
      outstanding: 1,
      nextSendAt: batch.createdAt,
    });
    expect(html).toContain("0:05");
    expect(html).toContain("EST. LEFT");
    expect(html).toContain("batch-countdown-track");
    expect(html).toContain(`stroke-dashoffset="0"`);
  });
});

it("reports in-flight sends separately without changing queued totals", async () => {
  findMany.mockResolvedValue([
    {
      id: batch.id,
      createdAt: new Date(batch.createdAt),
      sends: [
        {
          status: "QUEUED",
          deliveryState: "ATTEMPTING",
          dispatchedAt: new Date(),
          attemptedAt: new Date(),
          sentAt: null,
        },
        {
          status: "QUEUED",
          deliveryState: "READY",
          createdAt: new Date(batch.createdAt),
          dispatchedAt: null,
          attemptedAt: null,
          sentAt: null,
        },
        {
          status: "FAILED",
          deliveryState: "UNCERTAIN",
          dispatchedAt: new Date(),
          attemptedAt: new Date(),
          sentAt: null,
        },
      ],
    },
  ]);
  const data = await readCampaignProgress(
    { id: "test-user", nextSendAt: new Date("2026-10-09T10:01:33Z") },
    [batch.id],
  );
  expect(data).toMatchObject({
    queued: 2,
    outstanding: 2,
    sending: 1,
    review: 1,
    finishedAt: null,
    delays: [],
  });
  expect(findMany).toHaveBeenCalledWith(
    expect.objectContaining({
      where: expect.objectContaining({ userId: "test-user" }),
    }),
  );
});

const delay = {
  sendId: "email-1",
  recipient: "[REDACTED_EMAIL]",
  state: "READY" as const,
  startedAt: batch.createdAt,
};
it.each([
  ["2026-10-09T10:02:29.999Z", false, false],
  ["2026-10-09T10:02:30Z", true, false],
  ["2026-10-09T10:03:59.999Z", true, false],
  ["2026-10-09T10:04:00Z", true, true],
])("per-email notice boundaries at %s", (observedAt, notice, recovery) => {
  const html = render({
    ...batch,
    queued: 10,
    outstanding: 10,
    observedAt,
    delays: [delay],
  });
  expect(html.includes("[REDACTED_EMAIL] — Taking longer than usual.")).toBe(
    notice,
  );
  expect(html.includes("Mailloop retries automatically")).toBe(recovery);
  expect(html.includes("Cancel this email")).toBe(recovery);
});
it("protects active attempts at four minutes and keeps the recipient notice", () => {
  const html = render({
    ...batch,
    queued: 10,
    outstanding: 10,
    sending: 1,
    observedAt: "2026-10-09T10:05:00Z",
    delays: [{ ...delay, state: "ATTEMPTING" }],
  });
  expect(html.match(/Taking longer than usual/g)).toHaveLength(1);
  expect(html).not.toContain("Cancel this email");
  expect(html).not.toContain("Mailloop retries automatically");
});
it("never warns from five minutes of batch duration alone", () => {
  const html = render({
    ...batch,
    sent: 9,
    queued: 1,
    outstanding: 1,
    observedAt: "2026-10-09T10:05:00Z",
    delays: [{ ...delay, startedAt: "2026-10-09T10:04:30Z" }],
  });
  expect(html).not.toContain("Taking longer than usual");
});

const queued = (id: string, overrides = {}) => ({
  id,
  recipientEmail: `${id}@example.com`,
  deliveryState: "READY",
  createdAt: new Date(batch.createdAt),
  attemptedAt: null,
  availableAt: null,
  queueExpiresAt: null,
  ...overrides,
});
async function readQueue(
  rows: ReturnType<typeof queued>[],
  nextSendAt: Date | null = null,
) {
  queueFindMany.mockResolvedValue(rows);
  findMany.mockResolvedValue([
    {
      id: batch.id,
      createdAt: new Date(batch.createdAt),
      sends: rows.map((row) => ({
        ...row,
        status: "QUEUED",
        dispatchedAt: null,
      })),
    },
  ]);
  return readCampaignProgress({ id: "test-user", nextSendAt }, [batch.id]);
}
it("uses attemptedAt only and does not age the emails behind an attempt", async () => {
  const attemptedAt = new Date("2026-10-09T10:03:00Z");
  aggregate.mockResolvedValueOnce({
    _max: {
      sentAt: new Date("2026-10-09T10:04:00Z"),
      cancelledAt: null,
      attemptedAt: null,
    },
  });
  const data = await readQueue([
    queued("first", { deliveryState: "ATTEMPTING", attemptedAt }),
    queued("second"),
  ]);
  expect(data?.delays).toEqual([
    {
      sendId: "first",
      recipient: "[REDACTED_EMAIL]",
      state: "ATTEMPTING",
      startedAt: attemptedAt.toISOString(),
    },
  ]);
});
it("keeps stalled pickup timing stable through polling and publication retries", async () => {
  const rows = [queued("first"), queued("second")];
  const first = await readQueue(rows);
  const retry = await readQueue(
    rows.map((row) => ({
      ...row,
      dispatchedAt: new Date(),
      dispatchAttemptedAt: new Date(),
    })),
  );
  expect(first?.delays).toEqual([
    {
      sendId: "first",
      recipient: "[REDACTED_EMAIL]",
      state: "READY",
      startedAt: new Date(batch.createdAt).toISOString(),
    },
  ]);
  expect(retry?.delays).toEqual(first?.delays);
});
it("starts the next email after preceding delivery or cancellation activity", async () => {
  const cancelledAt = new Date("2026-10-09T10:04:00Z");
  aggregate.mockResolvedValueOnce({
    _max: { sentAt: new Date(batch.createdAt), attemptedAt: null, cancelledAt },
  });
  const data = await readQueue([queued("second")]);
  expect(data?.delays[0].startedAt).toBe(cancelledAt.toISOString());
});
it("honors availability, pacing, expiration and queue order", async () => {
  const data = await readQueue(
    [
      queued("scheduled", { availableAt: new Date("2099-01-01") }),
      queued("expired", { queueExpiresAt: new Date("2020-01-01") }),
      queued("eligible", { availableAt: new Date("2026-10-09T10:01:00Z") }),
      queued("behind"),
    ],
    new Date("2026-10-09T10:02:00Z"),
  );
  expect(data?.delays).toEqual([
    {
      sendId: "eligible",
      recipient: "[REDACTED_EMAIL]",
      state: "READY",
      startedAt: "2026-10-09T10:02:00.000Z",
    },
  ]);
  expect(
    (await readQueue([queued("future")], new Date("2099-01-01")))?.delays,
  ).toEqual([]);
});
it("cleans up terminal emails and respects queue heads outside displayed batches", async () => {
  queueFindMany.mockResolvedValue([queued("outside"), queued("inside")]);
  findMany.mockResolvedValue([
    {
      id: batch.id,
      createdAt: new Date(batch.createdAt),
      sends: [{ ...queued("inside"), status: "SENT" }],
    },
  ]);
  expect(
    (
      await readCampaignProgress({ id: "test-user", nextSendAt: null }, [
        batch.id,
      ])
    )?.delays,
  ).toEqual([]);
  expect(queueFindMany).toHaveBeenLastCalledWith(
    expect.objectContaining({
      where: expect.objectContaining({ campaign: { userId: "test-user" } }),
    }),
  );
});

it.each([
  ["SENT", "DONE"],
  ["FAILED", "DONE"],
  ["CANCELLED", "DONE"],
  ["FAILED", "UNCERTAIN"],
])("removes individual notices for %s/%s", async (status, deliveryState) => {
  queueFindMany.mockResolvedValue([]);
  findMany.mockResolvedValue([
    {
      id: batch.id,
      createdAt: new Date(batch.createdAt),
      sends: [
        {
          ...queued("finished"),
          status,
          deliveryState,
          sentAt: null,
          cancelledAt: null,
        },
      ],
    },
  ]);
  const data = await readCampaignProgress(
    { id: "test-user", nextSendAt: null },
    [batch.id],
  );
  expect(data?.delays).toEqual([]);
  const html = render(data!);
  expect(html).not.toContain("Taking longer than usual");
  if (deliveryState === "UNCERTAIN")
    expect(html).toContain("Delivery needs review");
});
it("does not warn during any of ten normal thirty-second deliveries", () => {
  const createdAt = Date.parse(batch.createdAt);
  for (let sent = 0; sent < 10; sent++) {
    const html = render({
      ...batch,
      sent,
      queued: 10 - sent,
      outstanding: 10 - sent,
      sending: 1,
      observedAt: new Date(createdAt + (sent + 1) * 30_000).toISOString(),
      delays: [
        {
          ...delay,
          state: "ATTEMPTING",
          startedAt: new Date(createdAt + sent * 30_000).toISOString(),
        },
      ],
    });
    expect(html).not.toContain("Taking longer than usual");
    expect(html).not.toContain("Mailloop retries automatically");
  }
});
